`timescale 1ns/1ps
// GATE-LEVEL post-map simulation: simulate the ACTUAL synthesized netlist
// (z80cpm_impl1_mapvo.vo) generated by Diamond, with SDF timing annotation.
// The .vo top is z80cpm_brevia2 (ports include the SRAM bus). We drive the
// clock/reset, attach the external SRAM model, and check the LED output.
// led[6:0] = ~led_reg[6:0]; so led[6:0]=0x55 => the core WROTE 0xAA to port 0x40,
// led[6:0]=0x7F => no write (core mis-executes on the mapped netlist).
module tb_gl;
  reg        clk_in = 0;
  reg        rst_n  = 0;
  reg  [7:0] sw     = 8'h00;
  reg        uart_rx = 1'b1;
  wire       uart_tx;
  wire [7:0] led;
  wire [16:0] sram_addr; wire sram_cen, sram_oen, sram_wen; wire [7:0] sram_data;

  z80cpm_brevia2 u_dut(.clk_in(clk_in), .rst_n(rst_n), .led(led), .sw(sw),
                       .uart_rx(uart_rx), .uart_tx(uart_tx),
                       .sram_addr(sram_addr), .sram_cen(sram_cen),
                       .sram_oen(sram_oen), .sram_wen(sram_wen), .sram_data(sram_data));
  sram_model u_sram(.addr(sram_addr), .cen(sram_cen), .oen(sram_oen),
                    .wen(sram_wen), .data(sram_data));

  initial $sdf_annotate("z80cpm_impl1_mapvo.sdf", u_dut);

  always #10 clk_in = ~clk_in;   // 50 MHz input

  initial begin
    #200 rst_n = 1;
    #2000000;                       // ~2 ms
    $display("led=%b  (led[6:0]=~led_reg -> 0x55=wrote 0xAA, 0x7F=no write)", led);
    if ((led & 8'h7F) == 8'h55)
      $display("PASS: mapped netlist executes OUT 40 and latches 0xAA");
    else
      $display("FAIL: mapped netlist does NOT write 0xAA (led=%b)", led);
    $finish;
  end
endmodule
